   111  inline Endianness getTiffByteOrder(const ByteStream& bs, uint32 pos,
   112                                     const char* context = "") {
   113    if (bs.hasPatternAt("II", 2, pos))
   114      return Endianness::little;
   115    if (bs.hasPatternAt("MM", 2, pos))
   116      return Endianness::big;
